package com.citacloud.springboot.contacloud.app.services;import com.citacloud.springboot.contacloud.app.dto.AjusteInventarioReporteData;import net.sf.jasperreports.engine.*;import net.sf.jasperreports.engine.data.JRBeanCollectionDataSource;import org.springframework.stereotype.Service;import java.io.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class AjusteInventarioPdfService{private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy"),TIME=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");private volatile JasperReport compiled;
 public byte[] generar(AjusteInventarioReporteData d,ZoneId z){try{return JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(report(),params(d,z),new JRBeanCollectionDataSource(d.lineas(),false)));}catch(JRException e){throw new ReglaNegocioException("No fue posible generar el PDF del ajuste.",e);}}
 static Map<String,Object> params(AjusteInventarioReporteData d,ZoneId z){Map<String,Object> p=new HashMap<>();p.put("companyTradeName",value(d.empresaNombreComercial()));p.put("companyLegalName",optional(d.empresaRazonSocial()));p.put("companyTaxIdentification",PurchaseOrderPdfService.formatTaxIdentification(d.empresaIdentificacion()));p.put("companyAddress",optional(d.empresaDireccion()));p.put("companyPhone",PurchaseOrderPdfService.formatPhone(d.empresaTelefono()));p.put("companyEmail",optional(d.empresaCorreo()));p.put("companyLogo",d.empresaLogo()==null?null:new ByteArrayInputStream(d.empresaLogo()));p.put("adjustmentNumber",value(d.numero()));p.put("status",value(d.estado()).toUpperCase());p.put("effectiveDate",d.fecha()==null?"—":DATE.format(d.fecha()));p.put("warehouse",value(d.almacen()));p.put("branch",value(d.sucursal()));p.put("reason",value(d.motivo()));p.put("reference",value(d.referencia()));p.put("notes",value(d.observacion()));p.put("confirmedBy",value(d.confirmadaPor()));p.put("confirmedAt",format(d.confirmadaEn(),z));p.put("generatedBy",value(d.generadoPor()));p.put("generatedAt",format(d.generadoEn(),z));return p;}
 private JasperReport report()throws JRException{if(compiled!=null)return compiled;synchronized(this){if(compiled==null){try(InputStream in=getClass().getResourceAsStream("/reports/inventory-adjustment/inventory-adjustment.jrxml")){if(in==null)throw new ReglaNegocioException("No se encontró la plantilla del ajuste de inventario.");compiled=JasperCompileManager.compileReport(in);}catch(IOException e){throw new ReglaNegocioException("No fue posible preparar el PDF del ajuste.",e);}}return compiled;}}private static String format(OffsetDateTime d,ZoneId z){return d==null?"—":TIME.format(d.atZoneSameInstant(z));}private static String value(String x){return x==null||x.isBlank()?"—":x.trim();}private static String optional(String x){return x==null||x.isBlank()?null:x.trim();}}
